# --- Catálogo de sequências (SQLite) ---
DB_PATH = 'data/sequencias.db'

SEQUENCIAS_ORIGINAIS = [
    (0, ['Bm', 'G', 'D', 'A']),
    (1, ['C', 'G', 'Am', 'F']),
